export class UserActionBroker{valid(e){return["click","hover","mousedown","mouseup","visibility","keypress","keydown","keyup","focusin","focusout"].includes(e)}fire(e,t,n,o,s=!1){const r=Object.assign({},n,{eventType:t});if(o.dispatchEvent(new CustomEvent(e,{bubbles:!0,composed:!0,cancelable:!0,detail:r})),s){const e=globalThis.document.createElement("pre");e.textContent=JSON.stringify(r,null,2),o.replaceChildren(e)}}}export const UABroker=new UserActionBroker;